import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.q07Y7wJQ.js";var i=JSON.parse(`{"title":"Context Menu","description":"","frontmatter":{"prev":{"text":"Settings","link":"/documentation/settings"},"next":{"text":"Keyboard Shortcuts","link":"/documentation/extension/keyboard-shortcuts"}},"headers":[],"relativePath":"documentation/extension/context-menu.md","filePath":"documentation/extension/context-menu.md","lastUpdated":1788551488000}`),a={name:`documentation/extension/context-menu.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="context-menu" tabindex="-1">Context Menu <a class="header-anchor" href="#context-menu" aria-label="Permalink to “Context Menu”">​</a></h1><p>Access core extension actions, DOM element inspection tools, and selector copy helpers directly from your browser&#39;s right-click context menu.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>The Excellent Data Filler context menu is accessible in two distinct contexts:</p><ol><li><strong>Page Context Menu</strong>: Right-click anywhere on an active web page to inspect elements, configure forms, or copy element selectors.</li><li><strong>Toolbar Icon Context Menu</strong>: Right-click the extension icon in the browser toolbar for quick status controls, permission management, and right-click unblocking.</li></ol><div style="display:flex;gap:20px;flex-wrap:wrap;margin:20px 0;"><div style="flex:1;min-width:280px;"><h4 style="margin:0 0 8px 0;">Web Page Context Menu</h4><img src="/image/context-menu-page.png" alt="Page Context Menu" style="width:100%;border-radius:8px;border:1px solid var(--vp-c-divider);"></div><div style="flex:1;min-width:280px;"><h4 style="margin:0 0 8px 0;">Toolbar Icon Context Menu</h4><img src="/image/context-menu-toolbar.png" alt="Toolbar Icon Context Menu" style="width:100%;border-radius:8px;border:1px solid var(--vp-c-divider);"></div></div><hr><h2 id="menu-actions-reference" tabindex="-1">Context Menu Actions Reference <a class="header-anchor" href="#menu-actions-reference" aria-label="Permalink to “Context Menu Actions Reference”">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Location</th><th>Shortcut</th><th>Description</th></tr></thead><tbody><tr><td><strong>Extension is ON</strong></td><td>Page &amp; Toolbar</td><td><kbd>Alt</kbd> + <kbd>Q</kbd></td><td>Master toggle showing active status (<code>✓</code>). Click to toggle automation on or off.</td></tr><tr><td><strong>Allow Right Click?</strong></td><td>Toolbar Only</td><td>—</td><td>Forcefully re-enables right-click menus on sites that disable right-clicking.</td></tr><tr><td><strong>Inspect Elements</strong></td><td>Page &amp; Toolbar</td><td><kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>I</kbd></td><td>Launches the interactive Element Details inspection modal.</td></tr><tr><td><strong>Open Sidebar</strong></td><td>Page &amp; Toolbar</td><td>—</td><td>Opens the extension sidebar <em>(Under Development)</em>.</td></tr><tr><td><strong>Insert Site</strong></td><td>Page Only</td><td><kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>S</kbd></td><td>Registers the active website as a new automation site.</td></tr><tr><td><strong>Insert Form</strong></td><td>Page Only</td><td><kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>F</kbd></td><td>Adds a new form to the current active site.</td></tr><tr><td><strong>Copy Field</strong></td><td>Page Only</td><td><kbd>Alt</kbd> + <kbd>C</kbd></td><td>Copies selected field(s) configuration from the extension.</td></tr><tr><td><strong>Copy Form Response</strong></td><td>Page Only</td><td><kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>R</kbd></td><td>Copies element text, selector, XPath, and URL for response rules.</td></tr><tr><td><strong>Copy Element Selector Address</strong></td><td>Page Only</td><td><kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>C</kbd></td><td>Copies the CSS selector of the right-clicked element.</td></tr><tr><td><strong>Copy Element XPath Selector Address</strong></td><td>Page Only</td><td><kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>X</kbd></td><td>Copies the XPath expression of the right-clicked element.</td></tr><tr><td><strong>Copy text of selected element</strong></td><td>Page Only</td><td><kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>T</kbd></td><td>Copies the visible text content of the element.</td></tr><tr><td><strong>Copy html of selected element</strong></td><td>Page Only</td><td><kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>H</kbd></td><td>Copies the outer HTML source code of the element.</td></tr><tr><td><strong>Copy name of selected option</strong></td><td>Page Only</td><td><kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>N</kbd></td><td>Copies the visible text label of a <code>&lt;select&gt;</code> option.</td></tr><tr><td><strong>Copy value of selected option</strong></td><td>Page Only</td><td><kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>M</kbd></td><td>Copies the <code>value</code> attribute of a <code>&lt;select&gt;</code> option.</td></tr><tr><td><strong>Download select box options</strong></td><td>Page Only</td><td>—</td><td>Downloads all options of a dropdown menu as a data file.</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Open Sidebar Under Development</p><p>The <strong>Open Sidebar</strong> menu item is currently <strong>under active development</strong> and will be fully enabled in an upcoming version.</p></div><hr><h2 id="inspect-elements" tabindex="-1"><img src="/svg/browser.svg" class="doc-icon" width="20" height="20" alt="Inspect Elements"> Inspect Elements <a class="header-anchor" href="#inspect-elements" aria-label="Permalink to “Inspect Elements”">​</a></h2><p>The <strong>Inspect Elements</strong> tool (<kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>I</kbd>) provides a built-in DOM inspector designed specifically for form automation setup without requiring browser DevTools.</p><h3 id="inspector-info" tabindex="-1">1. Info Tab <a class="header-anchor" href="#inspector-info" aria-label="Permalink to “1. Info Tab”">​</a></h3><p>Inspect DOM element metrics, hierarchical positions, and structural breadcrumb paths.</p><img src="/image/element-inspector-info.png" alt="Element Inspector Info Tab" style="max-width:480px;width:100%;border-radius:8px;margin:12px 0;"><ul><li><strong>Element Tag &amp; Classes</strong>: Identifies the HTML element tag (e.g., <code>&lt;li/&gt;</code>) and active classes.</li><li><strong>Breadcrumb Navigation</strong>: Shows full DOM hierarchy (<code>body &gt; div#app &gt; div.Layout &gt; div#VPContent</code>) with directional step navigation buttons (<code>↑</code>, <code>↓</code>, <code>←</code>, <code>→</code>).</li><li><strong>Text Content</strong>: Real-time extracted text content of the element.</li><li><strong>Dimensions &amp; Positioning</strong>: Displays pixel dimensions (<code>Width: 707px</code>, <code>Height: 26px</code>) and CSS positioning (<code>Position: static</code>, <code>Top</code>, <code>Left</code>, <code>Z-Index</code>).</li><li><strong>Header Actions</strong>: Quick controls to <strong>Hide</strong>, <strong>Copy HTML</strong>, Download element, Delete, or <strong>Clear</strong>.</li><li><strong>Docked Toolbar Controls</strong>: <ul><li><strong>Pause / Freeze</strong> (<kbd>⏸</kbd>): Freezes dynamic page states (tooltips, dropdowns) for inspection.</li><li><strong>Element Picker</strong> (<kbd>✦</kbd>): Click to highlight and inspect any other element on the page.</li><li><strong>Grid Overlay</strong>: Toggles alignment grid overlays.</li><li><strong>Edit</strong>: Edit element attributes directly.</li><li><strong>Close</strong> (<kbd>✕</kbd>): Dismisses the inspector overlay.</li></ul></li></ul><hr><h3 id="inspector-selector" tabindex="-1">2. Selector Tab <a class="header-anchor" href="#inspector-selector" aria-label="Permalink to “2. Selector Tab”">​</a></h3><p>Generate, test, and copy unique CSS selectors and XPath expressions.</p><img src="/image/element-inspector-selector.png" alt="Element Inspector Selector Tab" style="max-width:480px;width:100%;border-radius:8px;margin:12px 0;"><ul><li><strong>Live Selector / XPath Tester</strong>: Enter any custom selector query or XPath expression and click <strong>Find</strong> to verify matches in real-time.</li><li><strong>Real-Time Selector Filter</strong>: Search and filter through all discovered selectors with category counts (e.g., <code>All (112)</code>).</li><li><strong>Recommended Selectors</strong>: Displays high-priority selectors optimized for uniqueness and stability, complete with match count badges (e.g., <code>1 match</code>) and a one-click clipboard copy button.</li></ul><hr><h3 id="inspector-settings" tabindex="-1">3. Settings Tab <a class="header-anchor" href="#inspector-settings" aria-label="Permalink to “3. Settings Tab”">​</a></h3><p>Customize the appearance and behavior of the inspector overlay.</p><img src="/image/element-inspector-settings.png" alt="Element Inspector Settings Tab" style="max-width:480px;width:100%;border-radius:8px;margin:12px 0;"><ul><li><strong>Panel Width</strong>: Customize the inspector modal width in pixels (default: <code>420px</code>).</li><li><strong>Font Size</strong>: Increase or decrease inspector text sizing with <code>-</code>, <code>+</code>, and <code>Reset</code> controls.</li><li><strong>Modal Zoom</strong>: Adjust inspector magnification percentage with <code>-</code>, <code>+</code>, and <code>Reset</code> controls.</li><li><strong>Selector Test Trigger</strong>: Configure how selectors are tested (default: <code>Click only (Default)</code>).</li></ul><hr><h2 id="allow-right-click" tabindex="-1"><img src="/svg/settings.svg" class="doc-icon" width="20" height="20" alt="Allow Right Click"> Allow Right Click? <a class="header-anchor" href="#allow-right-click" aria-label="Permalink to “Allow Right Click?”">​</a></h2><p>Some protected or restricted websites use custom JavaScript event listeners to disable right-clicking, preventing users from opening browser context menus or inspecting form elements.</p><h3 id="how-to-bypass-right-click-restrictions" tabindex="-1">How to Bypass Right-Click Restrictions <a class="header-anchor" href="#how-to-bypass-right-click-restrictions" aria-label="Permalink to “How to Bypass Right-Click Restrictions”">​</a></h3><ol><li>Right-click the <strong>Excellent Data Filler</strong> icon in the browser toolbar.</li><li>Click <strong>Allow Right Click?</strong> (a checkmark <code>✓</code> confirms activation).</li><li>The extension overrides hostile event handlers, allowing you to right-click and use extension features freely on the page.</li></ol><div class="tip custom-block"><p class="custom-block-title">Global Configuration in Settings</p><p>You can also permanently automate right-click bypasses across all sites by configuring <strong>Allow Right-Click</strong> and <strong>Force Allow Right-Click</strong> under <img src="/svg/settings.svg" class="doc-icon" width="16" height="16" alt="Settings"> <a href="/documentation/settings.html#advanced-options">Global Settings &gt; Advanced Parsing Filters</a>.</p></div><hr><h2 id="copy-operations" tabindex="-1"><img src="/svg/code.svg" class="doc-icon" width="20" height="20" alt="Copy Operations"> Copy Operations &amp; Quick Actions <a class="header-anchor" href="#copy-operations" aria-label="Permalink to “Copy Operations &amp; Quick Actions”">​</a></h2><h3 id="copy-form-response-alt-shift-r" tabindex="-1">Copy Form Response (<kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>R</kbd>) <a class="header-anchor" href="#copy-form-response-alt-shift-r" aria-label="Permalink to “Copy Form Response (Alt + Shift + R)”">​</a></h3><p>Captures the complete diagnostic payload of an element to configure form submission response rules:</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;text&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Success&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;selector&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;#status-message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;xpath&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;//div[@id=&#39;status-message&#39;]&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://example.com/form&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="copy-field-alt-c" tabindex="-1">Copy Field (<kbd>Alt</kbd> + <kbd>C</kbd>) <a class="header-anchor" href="#copy-field-alt-c" aria-label="Permalink to “Copy Field (Alt + C)”">​</a></h3><p>Copies one or multiple field configurations directly from the extension interface to paste into another form or site.</p><h3 id="dropdown-option-helpers" tabindex="-1">Dropdown Option Helpers <a class="header-anchor" href="#dropdown-option-helpers" aria-label="Permalink to “Dropdown Option Helpers”">​</a></h3><ul><li><strong>Copy name of selected option</strong> (<kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>N</kbd>): Copies the user-facing option label.</li><li><strong>Copy value of selected option</strong> (<kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>M</kbd>): Copies the underlying form submission <code>value</code>.</li><li><strong>Download select box options</strong>: Exports all dropdown entries from a <code>&lt;select&gt;</code> element into a structured file for template building.</li></ul><hr><h2 id="related-documentation" tabindex="-1">Related Documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to “Related Documentation”">​</a></h2><ul><li><img src="/svg/click.svg" class="doc-icon" width="16" height="16" alt="Keyboard Shortcuts"> <a href="/documentation/extension/keyboard-shortcuts.html">Keyboard Shortcuts Reference</a></li><li><img src="/svg/settings.svg" class="doc-icon" width="16" height="16" alt="Settings"> <a href="/documentation/settings.html">Extension Settings</a></li><li><img src="/svg/form.svg" class="doc-icon" width="16" height="16" alt="Field Types"> <a href="/documentation/form-fields/field-types.html">Field Types</a></li></ul>`,45)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};